import '@servicenow/sdk/global'
import { Flow, trigger, wfa, action } from '@servicenow/sdk/automation'
import { IntegerColumn } from '@servicenow/sdk/core'

/**
 * Duration with Datapills Example
 * Demonstrates: Using wfa.dataPill() inside Duration() helper
 */
Flow(
    {
        $id: Now.ID['duration_datapills_example'],
        name: 'Duration with Datapills Example',
        description: 'Demonstrates using datapills inside Duration expressions',
        runAs: 'system',
        flowVariables: {
            durationDays: IntegerColumn({
                label: 'Duration Days',
                mandatory: true,
            }),
            durationHours: IntegerColumn({
                label: 'Duration Hours',
                mandatory: true,
            }),
            durationMinutes: IntegerColumn({
                label: 'Duration Minutes',
                mandatory: true,
            }),
            durationSeconds: IntegerColumn({
                label: 'Duration Seconds',
                mandatory: true,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['duration_trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_setting: 'both',
            run_when_user_list: [],
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        // Initialize flow variables
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['init_duration_vars'],
                annotation: 'Initialize duration variables',
            },
            _params.flowVariables,
            {
                durationDays: 5,
                durationHours: 3,
                durationMinutes: 30,
                durationSeconds: 45,
            }
        )

        // Example 1: Duration with datapills from flow variables
        wfa.action(
            'action.core.log',
            {
                $id: Now.ID['log_with_duration_vars'],
                annotation: 'Log with Duration using flow variable datapills',
            },
            {
                log_level: 'info',
                log_message: 'Duration test with flow variables',
                duration_field: Duration({
                    days: 5,
                    hours: 3,
                    minutes: 30,
                    seconds: 45,
                }),
            }
        )

        // Example 2: Duration with datapills from trigger
        wfa.action(
            'action.core.log',
            {
                $id: Now.ID['log_with_duration_trigger'],
                annotation: 'Log with Duration using trigger datapills',
            },
            {
                log_level: 'info',
                log_message: 'Duration test with trigger',
                duration_field: Duration({
                    days: 1,
                    hours: 2,
                    minutes: 30,
                    seconds: 0,
                }),
            }
        )

        // Example 3: Duration with literal values
        wfa.action(
            'action.core.log',
            {
                $id: Now.ID['log_with_duration_literal_values'],
                annotation: 'Log with Duration using literal values',
            },
            {
                log_level: 'info',
                log_message: 'Duration test with action output',
                duration_field: Duration({
                    days: 2,
                    hours: 12,
                    minutes: 15,
                    seconds: 45,
                }),
            }
        )

        // Example 4: WaitForADuration with literal duration values
        wfa.flowLogic.waitForADuration({
            $id: Now.ID['wait_with_duration_literals'],
            annotation: 'Wait with Duration using literal values',
            durationType: 'explicit_duration',
            duration: Duration({
                days: 0,
                hours: 3,
                minutes: 30,
                seconds: 0,
            }),
        })

        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_duration_completion'],
            },
            {
                log_level: 'info',
                log_message: 'Duration with datapills test completed',
            }
        )
    }
)
